        "gh api --repo o/r x",
        "gh pr list",
        "cargo publish --manifest-path /x --locked",
        "cargo info foo --registry crates-io",
        "cargo info foo --offline",
        "git -c tag.gpgSign=false tag -a -m msg --no-sign -- v1 abc",
        "git tag --force v1",
